function alertLocalized(message){window.alert(translateValue(message))}
function showShieldLockNotice(){const dialog=$('shield-lock-notice-dialog');if(dialog&&!dialog.open)dialog.showModal()}
function confirmLocalized(message){return window.confirm(translateValue(message))}
function translateValue(value){if(state.language!=='en')return value;let translated=STATIC_UI_EN[value]||RUNTIME_UI_EN[value]||value;return translated.replace(/^Próxima temporada em /,'Next season in ').replace(/ min para a sua meta de hoje\.$/,' min left for today’s goal.').replace(/ sessões · /,' sessions · ').replace(/ itens$/,' items').replace(/ sessões$/,' sessions').replace(/ itens$/,' items').replace(/Item comum/g,'Common item').replace(/Item incomum/g,'Uncommon item').replace(/Item raro/g,'Rare item').replace(/Item lendário/g,'Legendary item').replace(/Item suprema/g,'Supreme item').replace(/Item amaldiçoado/g,'Cursed item')}
const translatedAttributeOriginals=new WeakMap();
function translateStaticUI(root=document.body){if(!root)return;const elements=[root,...root.querySelectorAll('*')];elements.forEach(element=>{if(element.dataset?.i18nDynamic==='true')return;['placeholder','title','aria-label','alt'].forEach(attribute=>{const value=element.getAttribute?.(attribute);if(value===null)return;let originals=translatedAttributeOriginals.get(element);if(!originals){originals={};translatedAttributeOriginals.set(element,originals)}if(!(attribute in originals))originals[attribute]=value;const next=state.language==='en'?translateValue(originals[attribute]):originals[attribute];if(value!==next)element.setAttribute(attribute,next)});if([...element.children].length)return;const text=element.textContent;if(!text.trim())return;if(!element.dataset.i18nText)element.dataset.i18nText=text;const next=state.language==='en'?translateValue(element.dataset.i18nText):element.dataset.i18nText;if(text!==next)element.textContent=next})}

function sessionLabel(){const value=$('intention')?.value||'Foco profundo';return state.sessionType==='pomo'?`Pomo — ${value}`:state.sessionType==='cronometro'?`Cronômetro — ${value}`:value}

function openAudioStore(){return new Promise((resolve,reject)=>{const request=indexedDB.open('focapy-media',1);request.onupgradeneeded=()=>request.result.createObjectStore('sounds');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function saveCustomAmbient(file){const db=await openAudioStore();await new Promise((resolve,reject)=>{const tx=db.transaction('sounds','readwrite');tx.objectStore('sounds').put(file,'custom');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});setCustomAmbient(file,file.name)}
async function restoreCustomAmbient(){try{const db=await openAudioStore();const file=await new Promise((resolve,reject)=>{const tx=db.transaction('sounds','readonly');const request=tx.objectStore('sounds').get('custom');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});if(file)setCustomAmbient(file,file.name||'Meu som',false)}catch{}}
function setCustomAmbient(file,name,selectIt=true){if(state.customAudioUrl)URL.revokeObjectURL(state.customAudioUrl);state.customAudioUrl=URL.createObjectURL(file);const select=$('ambient-select');let option=select.querySelector('option[value="custom"]');if(!option){option=document.createElement('option');option.value='custom';select.append(option)}option.textContent=name||'Meu som';if(selectIt){state.ambientTrack='custom';select.value='custom';saveState()}else if(state.ambientTrack==='custom')select.value='custom'}
function soundKey(id){return `completion:${id}`}
function isSupportedAudio(file){return Boolean(file)&&(/\.(mp3|wav)$/i.test(file.name)||['audio/mpeg','audio/wav','audio/x-wav','audio/wave'].includes(file.type))}
function soundUrl(id){return state.completionSoundUrls?.[id]||null}
function isCustomCompletionTone(tone=state.completionTone){return typeof tone==='string'&&tone.startsWith('uploaded:')}
function selectBuiltInCompletionTone(minutes){if(!state.completionToneManual&&!isCustomCompletionTone())state.completionTone=completionToneForMinutes(minutes)}
function normalizeCompletionTone(tone){return isCustomCompletionTone(tone)?tone:['gongo-1','gongo-2','gongo-3'].includes(tone)?tone:'gongo-1'}
function renderCompletionSoundLibrary(){const select=$('completion-sound-select'),library=$('completion-sound-library');if(!select||!library)return;select.replaceChildren(new Option('1 Gongo','gongo-1'),new Option('2 Gongos','gongo-2'),new Option('3 Gongos','gongo-3'));state.completionSounds.forEach(sound=>select.append(new Option(sound.name,`uploaded:${sound.id}`)));if(![...select.options].some(option=>option.value===state.completionTone))state.completionTone='gongo-1';select.value=state.completionTone;library.replaceChildren();state.completionSounds.forEach(sound=>{const row=document.createElement('div');row.className='completion-sound-row';const name=document.createElement('b');name.textContent=sound.name;const use=document.createElement('button');use.className='text-button';use.type='button';use.textContent=state.completionTone===`uploaded:${sound.id}`?'Em uso':'Usar';use.onclick=()=>{state.completionTone=`uploaded:${sound.id}`;saveState();renderCompletionSoundLibrary()};const test=document.createElement('button');test.className='text-button';test.type='button';test.textContent='Testar';test.onclick=()=>playCompletionSound(`uploaded:${sound.id}`);const remove=document.createElement('button');remove.className='text-button remove-sound';remove.type='button';remove.textContent='Remover';remove.onclick=()=>deleteCompletionSound(sound.id);row.append(name,use,test,remove);library.append(row)});}
async function saveCompletionSound(file){if(!isSupportedAudio(file))return alertLocalized('Selecione um arquivo MP3 ou WAV.');const id=crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;const db=await openAudioStore();await new Promise((resolve,reject)=>{const tx=db.transaction('sounds','readwrite');tx.objectStore('sounds').put(file,soundKey(id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});state.completionSoundUrls??={};state.completionSoundUrls[id]=URL.createObjectURL(file);state.completionSounds.push({id,name:file.name||'Som de conclusão'});state.completionTone=`uploaded:${id}`;state.completionToneManual=true;saveState();renderCompletionSoundLibrary()}
async function deleteCompletionSound(id){const db=await openAudioStore();await new Promise((resolve,reject)=>{const tx=db.transaction('sounds','readwrite');tx.objectStore('sounds').delete(soundKey(id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});if(state.completionSoundUrls?.[id])URL.revokeObjectURL(state.completionSoundUrls[id]);delete state.completionSoundUrls?.[id];state.completionSounds=state.completionSounds.filter(sound=>sound.id!==id);if(state.completionTone===`uploaded:${id}`)state.completionTone='default';saveState();renderCompletionSoundLibrary()}
async function restoreCompletionSounds(){try{const db=await openAudioStore();state.completionSoundUrls={};for(const sound of state.completionSounds){const file=await new Promise((resolve,reject)=>{const tx=db.transaction('sounds','readonly');const request=tx.objectStore('sounds').get(soundKey(sound.id));request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});if(file)state.completionSoundUrls[sound.id]=URL.createObjectURL(file)}renderCompletionSoundLibrary()}catch{}}

