function addCurrentTask(){const input=$('new-task'),previous=state.tasks.length,tag=$('new-task-tag')?.value||'',definition=state.tags.find(item=>item.name===tag),color=definition?.color||'',fontColor=definition?.fontColor||'#15382e';state.tasks=addTask(state.tasks,input.value,tag,color,fontColor);if(state.tasks.length===previous){input.setCustomValidity('Escolha uma tarefa nova.');input.reportValidity();return}input.value='';input.setCustomValidity('');saveState();renderTasks()}
