function saveTagEdits(originalName,nameInput,colorInput,fontColorInput){const nextName=String(nameInput.value||'').trim();if(!nextName){nameInput.setCustomValidity('Informe um nome para a categoria.');nameInput.reportValidity();return}if(!validHexColor(colorInput.value)||!validHexColor(fontColorInput.value)){colorInput.setCustomValidity('Use uma cor hexadecimal no formato #RRGGBB.');colorInput.reportValidity();return}nameInput.setCustomValidity('');colorInput.setCustomValidity('');const renamed=renameSessionTag(state.tags,originalName,nextName);if(nextName.toLocaleLowerCase()!==originalName.toLocaleLowerCase()&&!renamed.some(tag=>tag.name===nextName)){nameInput.setCustomValidity('Já existe uma categoria com esse nome.');nameInput.reportValidity();return}state.tags=updateSessionTagFontColorInList(updateSessionTagColorInList(renamed,nextName,colorInput.value),nextName,fontColorInput.value);if(state.selectedTag===originalName)state.selectedTag=nextName;if(state.editingTag===originalName)state.editingTag=nextName;saveState();renderSessionTags();}
function deleteTag(name){state.tags=removeSessionTag(state.tags,name);const cleared=clearDeletedSessionTagReferences(state.current,name);state.current=cleared.current;if(cleared.selectedTag!==undefined)state.selectedTag=cleared.selectedTag;if(state.editingTag===name)state.editingTag='';saveState();renderSessionTags();renderTimer();}
function renderCategoryDonut(stats){const donut=$('category-donut'),total=$('category-donut-total'),summary=$('category-donut-summary');if(!donut||!total||!summary)return;summary.replaceChildren();const categories=stats.categorySeries.filter(item=>item.points.some(Boolean));const minutes=categories.reduce((sum,item)=>sum+item.points.reduce((n,value)=>n+value,0),0);total.textContent=`${minutes} min`;if(!minutes){donut.style.background='conic-gradient(#e8e2d6 0 100%)';summary.innerHTML='<p class="muted">Sem categorias neste período.</p>';return}let angle=0;const segments=categories.map(item=>{const value=item.points.reduce((sum,point)=>sum+point,0),end=angle+value/minutes*360,part=`${item.color} ${angle}deg ${end}deg`;angle=end;return part});donut.style.background=`conic-gradient(${segments.join(',')})`;categories.forEach(item=>{const value=item.points.reduce((sum,point)=>sum+point,0),row=document.createElement('div'),percent=document.createElement('b'),duration=document.createElement('span'),tag=document.createElement('span'),dot=document.createElement('i');percent.textContent=`${Math.round(value/minutes*100)}%`;duration.textContent=`${value} min`;dot.style.background=item.color;tag.append(dot,document.createTextNode(item.tag));row.append(percent,duration,tag);summary.append(row)})}
function renderCategoryStatisticsChart(stats){const chart=$('category-statistics-chart'),legend=$('category-statistics-legend');if(!chart||!legend)return;chart.replaceChildren();legend.replaceChildren();const max=Math.max(1,...stats.categorySeries.flatMap(item=>item.points));if(!stats.categorySeries.length){chart.innerHTML='<p class="muted">Conclua sessões com categoria para visualizar o desempenho.</p>';return}stats.series.forEach((point,index)=>{const column=document.createElement('div');column.className='category-chart-column';const stack=document.createElement('div');stack.className='category-chart-stack';stats.categorySeries.forEach(item=>{const value=item.points[index];if(!value)return;const bar=document.createElement('i');bar.style.height=`${Math.max(3,Math.round(value/max*100))}%`;bar.style.background=item.color;bar.title=`${item.tag}: ${value} min`;stack.append(bar)});const label=document.createElement('small');label.textContent=point.label;column.append(stack,label);chart.append(column)});stats.categorySeries.forEach(item=>{const row=document.createElement('span');const dot=document.createElement('i');dot.style.background=item.color;row.append(dot,document.createTextNode(`${item.tag} · ${item.points.reduce((sum,value)=>sum+value,0)} min`));legend.append(row)})}
function renderStatistics(){const stats=statisticsForPeriod(state.sessions,state.statsPeriod);const labels={daily:'Diário',weekly:'Semanal',monthly:'Mensal',annual:'Anual'};$('stats-total-minutes').textContent=`${stats.totalMinutes} min`;$('stats-total-sessions').textContent=stats.totalSessions;$('statistics-period-label').textContent=labels[state.statsPeriod];$('category-chart-period-label').textContent=labels[state.statsPeriod];document.querySelectorAll('[data-stats-period]').forEach(button=>button.classList.toggle('active',button.dataset.statsPeriod===state.statsPeriod));const chart=$('statistics-chart');chart.replaceChildren();const max=Math.max(1,...stats.series.map(item=>item.minutes));stats.series.forEach(item=>{const column=document.createElement('div');column.className='chart-column';column.title=`${item.label}: ${item.minutes} min`;const value=document.createElement('span');value.className='chart-value';value.textContent=item.minutes||'';const bar=document.createElement('i');bar.style.height=`${Math.max(item.minutes?8:2,Math.round(item.minutes/max*100))}%`;const label=document.createElement('small');label.textContent=item.label;column.append(value,bar,label);chart.append(column)});renderCategoryDonut(stats);renderCategoryStatisticsChart(stats);const body=$('tag-statistics-body');body.replaceChildren();if(!stats.tags.length){const row=document.createElement('tr');row.innerHTML='<td colspan="3">Nenhuma sessão neste período.</td>';body.append(row);return}stats.tags.forEach(item=>{const row=document.createElement('tr');const category=document.createElement('td');const dot=document.createElement('i');dot.className='stats-tag-dot';const series=stats.categorySeries.find(series=>series.tag===item.tag);dot.style.background=series?.color||'#2d6c4d';category.style.color=series?.fontColor||'#15382e';category.append(dot,document.createTextNode(item.tag));[`${item.minutes} min`,String(item.sessions)].forEach(text=>{const cell=document.createElement('td');cell.textContent=text;row.append(cell)});row.prepend(category);body.append(row)});}

function setupPomoNumberPad(){const panel=$('pomo-options');if(!panel||panel.querySelector('#pomo-number-pad'))return;const pad=document.createElement('div');pad.id='pomo-number-pad';pad.className='pomo-number-pad';pad.hidden=true;pad.setAttribute('role','group');pad.setAttribute('aria-label','Teclado numérico do Pomodoro');pad.innerHTML='<button type="button" data-pomo-key="1">1</button><button type="button" data-pomo-key="2">2</button><button type="button" data-pomo-key="3">3</button><button type="button" data-pomo-key="4">4</button><button type="button" data-pomo-key="5">5</button><button type="button" data-pomo-key="6">6</button><button type="button" data-pomo-key="7">7</button><button type="button" data-pomo-key="8">8</button><button type="button" data-pomo-key="9">9</button><button type="button" data-pomo-key="0">0</button><button type="button" data-pomo-action="backspace">⌫</button><button type="button" data-pomo-action="done">Enter</button>';panel.append(pad);const inputs=['pomo-focus-minutes','pomo-break-minutes','pomo-cycles'].map(id=>$(id));let activeInput=null;const hide=()=>{pad.hidden=true;activeInput=null};inputs.forEach(input=>{if(!input)return;input.type='text';input.inputMode='none';input.onfocus=()=>{activeInput=input;activeInput.dataset.pomoFresh='true';pad.hidden=false};input.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();hide();input.blur();return}if(event.key==='Backspace'||event.key==='Delete'||event.key==='ArrowLeft'||event.key==='ArrowRight'||event.key==='Tab'||/^[0-9]$/.test(event.key))return;event.preventDefault()}});pad.querySelectorAll('[data-pomo-key]').forEach(button=>button.onpointerdown=event=>{event.preventDefault();if(!activeInput)return;if(activeInput.dataset.pomoFresh==='true'){activeInput.value='';activeInput.dataset.pomoFresh='false'}activeInput.value+=button.dataset.pomoKey;activeInput.dispatchEvent(new Event('input',{bubbles:true}));activeInput.focus()});pad.querySelector('[data-pomo-action="backspace"]').onpointerdown=event=>{event.preventDefault();if(!activeInput)return;activeInput.value=activeInput.value.slice(0,-1);activeInput.dispatchEvent(new Event('input',{bubbles:true}));activeInput.focus()};pad.querySelector('[data-pomo-action="done"]').onclick=()=>{if(activeInput)activeInput.blur();hide()}}
function syncPomoUI(){const active=state.sessionType==='pomo';$('rhythm-choices').hidden=state.sessionType!=='foco';const panel=$('pomo-options');if(panel)panel.hidden=!active||Boolean(state.current);const time=$('time-display');if(time)time.hidden=active&&!state.current;const focus=$('pomo-focus-minutes'),pause=$('pomo-break-minutes'),cycles=$('pomo-cycles');if(focus)focus.value=state.pomo.focusMinutes??'';if(pause)pause.value=state.pomo.breakMinutes??'';if(cycles)cycles.value=state.pomo.cycles??'';setupPomoNumberPad();document.querySelectorAll('.pomo-field,.pomo-cycles').forEach(node=>{const id=node.querySelector('input')?.id;const value=id==='pomo-focus-minutes'?state.pomo.focusMinutes:id==='pomo-break-minutes'?state.pomo.breakMinutes:state.pomo.cycles;node.classList.toggle('configured',active&&value!==null);});}
function applyPomoConfig(){state.pomo.focusMinutes=optionalPomoValue($('pomo-focus-minutes').value);state.pomo.breakMinutes=optionalPomoValue($('pomo-break-minutes').value);state.pomo.cycles=optionalPomoValue($('pomo-cycles').value);if(state.pomo.focusMinutes!==null)state.minutes=state.pomo.focusMinutes;$('pomo-focus-minutes').closest('.pomo-field').classList.remove('invalid');state.current=null;document.querySelectorAll('.duration').forEach(x=>x.classList.remove('selected'));saveState();syncPomoUI();renderTimer()}
function syncSessionViewport(){const active=state.current?.status==='running',locked=active&&state.strict;document.documentElement.classList.toggle('session-active',active);document.documentElement.classList.toggle('session-active-lock',locked);if(!active)return;document.querySelectorAll('.screen').forEach(screen=>screen.classList.toggle('active',screen.id==='focus'));document.querySelectorAll('.nav-button').forEach(button=>button.classList.toggle('active',button.dataset.screen==='focus'));}
function frameRunningTimer(){if(state.current?.status!=='running')return;const card=document.querySelector('.timer-card');if(card?.scrollIntoView)card.scrollIntoView({block:'center',inline:'nearest',behavior:'auto'});if(typeof window.scrollTo==='function'){const max=Math.max(0,(document.documentElement.scrollHeight||0)-window.innerHeight);window.scrollTo(0,Math.min(168,max))}}
function showIntentionTaskDialog(){const dialog=$('intention-task-dialog'),list=$('intention-task-list');list.replaceChildren();state.tasks.filter(task=>!task.done).forEach(task=>{const row=document.createElement('label');row.className='task-row';const check=document.createElement('input');check.type='checkbox';check.value=task.id;check.checked=state.sessionTaskIds.includes(task.id);check.onchange=()=>{state.sessionTaskIds=taskIdsForSession(state.tasks,check.checked?[...state.sessionTaskIds,task.id]:state.sessionTaskIds.filter(id=>id!==task.id));saveState();renderTimer()};const title=document.createElement('span');title.textContent=task.title;row.append(check,title);list.append(row)});if(!list.childElementCount)list.innerHTML='<p class="muted">Crie uma tarefa na aba Tarefas primeiro.</p>';dialog.showModal()}
