function renderGardens(){const calendar=$('garden-calendar');if(!calendar)return;calendar.replaceChildren();const gardens=[...state.commitments,{title:'Coleção atual',monthKey:state.monthKey,inventory:state.inventory,sessionsCount:state.sessions.length,current:true}].sort((a,b)=>b.monthKey.localeCompare(a.monthKey));gardens.forEach(garden=>{const button=document.createElement('button');button.className=`garden-month ${garden.current?'current':''}`;const [year,month]=garden.monthKey.split('-');button.textContent=new Date(Number(year),Number(month)-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});button.onclick=()=>{document.querySelectorAll('.garden-month').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');const detail=$('garden-detail');const plants=Object.entries(garden.inventory||{}).filter(([,count])=>count>0).map(([id,count])=>{const item=VEGETATION.find(v=>v.id===id);return item?`<span title="${item.name}">${item.icon} ×${count}</span>`:''}).join('');detail.innerHTML=`<h2>${garden.title}</h2><p class="muted">${garden.sessionsCount||0} sessões · ${Object.values(garden.inventory||{}).reduce((n,v)=>n+v,0)} itens</p><div class="garden-plants">${plants||'<small>Nenhum item registrado neste mês.</small>'}</div>`};calendar.append(button)});}
